  ui_story_31210601_44_dialog_content = "Sua força e astúcia envergonham até a mim, Lady Paloma.",
  ui_story_31210601_45_dialog_content = "Você me lisonjeia. Estou feliz que meu desempenho não o decepcionou.",
  ui_story_31210601_46_dialog_content = "Como poderia? As Rosas Negras devem realmente ser algo, considerando que até mesmo um segundo em comando pode derrubar um juiz.",
  ui_story_31210601_47_dialog_content = "Embora eu nunca tenha ouvido falar de sua gangue, estou ansioso para ver suas façanhas em um futuro próximo.",
  ui_story_31210601_48_dialog_content = "Os Black Roses sempre foram tão agressivos quanto nós discretos.",
  ui_story_31210601_49_dialog_content = "Não é esta a razão pela qual você nos abordou em primeiro lugar?",
  ui_story_31210601_50_dialog_content = "Ah... Sua mente perspicaz e língua rápida são igualadas apenas por sua beleza, milady.",
  ui_story_31210601_51_dialog_content = "Para ser honesto, minha rixa com o Hall of Justice remonta a muitos anos. Eles sempre estiveram dispostos a oprimir os outros com suas regras sem sentido - até mesmo seu próprio povo.",
  ui_story_31210601_52_dialog_content = "Você mesmo ouviu agora também. O Tribunal de Justiça colocou uma recompensa pela minha cabeça.",
  ui_story_31210601_53_dialog_content = "Considerando nosso inimigo mútuo, acredito que podemos trabalhar juntos muito bem.",
  ui_story_31210601_54_dialog_content = "Seria minha maior honra fazê-lo.",
  ui_story_31210601_55_dialog_content = "Seu elogio é apreciado, mas vamos ao que interessa, certo? Conte-me mais sobre esse seu trabalho.",
  ui_story_31210601_56_dialog_content = "Direto ao ponto, gostei!",
  ui_story_31210601_57_dialog_content = "Gostaria de pedir ajuda à sua organização para \"purgar\" uma área sob minha jurisdição.",
  ui_story_31210601_58_dialog_content = "Assim que terminar seu trabalho, chegarei com um séquito de soldados, fingiremos que estamos em uma batalha e então meus homens o deixarão ir.",
  ui_story_31210601_59_dialog_content = "Depois, voltaremos a Lumopolis para tratar de nossos ferimentos. Uma vez lá, direi que meu domínio foi atacado por eclipsitas e que fomos praticamente exterminados.",
  ui_story_31210601_60_dialog_content = "Você quer limpar seu próprio território de seu povo?",
  ui_story_31210601_61_dialog_content = "Por que você faria algo assim consigo mesmo?",
  ui_story_31210601_62_dialog_content = "Aquele deserto estéril não tem futuro como é agora. Estar preso a isso só vai me atrasar.",
  ui_story_31210601_63_dialog_content = "Já tenho um pedaço de terra fértil em vista, mas continua nas mãos de um adversário político. Com este plano, o Lorde da Cidade não terá escolha a não ser interceder em meu nome.",
  ui_story_31210601_64_dialog_content = "Será o último propósito que aqueles tolos me servirão.",
  ui_story_31210601_66_dialog_content = "<color=#e8d9bb>Clank—</color>",
  ui_story_31210601_67_dialog_content = "Considere este baú de joias seu pagamento adiantado.",
  ui_story_31210601_68_dialog_content = "Se você for bem-sucedido, posso torná-lo um oficial honorário da cidade depois, se quiser.",
  ui_story_31210601_69_dialog_content = "A lei estaria do seu lado mais uma vez; você não precisaria mais viver nas sombras.",
  ui_story_31210601_70_dialog_content = "Você nunca teria que trabalhar outro dia também. As ofertas do povo seriam mais do que suficientes para nos sustentar pelo resto de nossas vidas!",
  ui_story_31210601_71_dialog_content = "O que você disse? Acredito que uma oferta como essa requer muito pouca consideração.",
  ui_story_31210601_72_dialog_content = "Você pode esquecer de me tornar um oficial. Sempre fiz meu trabalho de acordo com o quanto me pagam.",
  ui_story_31210601_73_dialog_content = "Além disso, não tenho nenhum interesse em estabelecer qualquer tipo de vínculo com Lumopolis ou seus podres sistemas de governança.",
  ui_story_31210601_74_dialog_content = "Você realmente é diferente do resto. Pois bem, deixo meu brilhante e próspero futuro nas mãos das Rosas Negras.",
  ui_story_31210601_75_dialog_content = "Vocês, nobres hipócritas de Lumopolis, deveriam confiar seus futuros ao Deus da Luz, não a mim.",
  ui_story_31210601_76_dialog_content = "Não há nada de especial em mim.",
  ui_story_31210601_77_dialog_content = "Foi algo que eu disse? Ou talvez algo sobre minha oferta não tenha agradado você?",
  ui_story_31210601_78_dialog_content = "Oh não, sua oferta foi bastante razoável. Mais do que suficiente para garantir um futuro brilhante e próspero para mim, na verdade.",
  ui_story_31210601_79_dialog_content = "Infelizmente, o único futuro reservado para você está em uma cela de prisão do Hall of Justice.",
  ui_story_31210601_80_dialog_content = "O que?! Você... Qual é o significado disso?!",
  ui_story_31210601_81_dialog_content = "Ah... entendi! Eu entendo tudo agora! Vocês dois mestiços estavam trabalhando juntos o tempo todo para me envolver! É isso?!",
  ui_story_31210601_82_dialog_content = "Sim, eu me lembro agora! Da última vez, quando eu estava ensinando uma lição àqueles plebeus, você foi a \"freira\" que me atacou, não foi? A Rosa Negra!",
  ui_story_31210601_83_dialog_content = "Um disfarce tão brilhante. Eu nem te reconheci.",
  ui_story_31210601_84_dialog_content = "Quanto a você, Meritíssimo... Foi você quem impediu que ela me atacasse, se não me engano?",
  ui_story_31210601_85_dialog_content = "E pensar que vocês dois estavam trabalhando juntos esse tempo todo só para me prender...",
  ui_story_31210601_86_dialog_content = "Você não entendeu a profundidade da nossa cooperação.",
  ui_story_31210601_87_dialog_content = "Só a interrompi na hora porque, apesar de seu comportamento vil, você não havia violado as leis de Lumópolis.",
  ui_story_31210601_88_dialog_content = "Tenho a obrigação de proteger os cidadãos legais de Lumopolis, incluindo você. Minhas ações naquele dia não foram ensaiadas de forma alguma.",
  ui_story_31210601_89_dialog_content = "Falando nisso, você deveria saber... Não existe uma organização como a \"Rosa Negra\", e eu não sou chefe de gangue.",
  ui_story_31210601_90_dialog_content = "Quanto aos meus \"capangas\", se você estivesse prestando mais atenção, poderia ter reconhecido alguns de seus rostos.",
  ui_story_31210601_91_dialog_content = "Depois de se aproveitar de nós por tanto tempo... Não nos diga que você não se lembra da nossa aparência?",
  ui_story_31210601_92_dialog_content = "Vocês pessoas...",
  ui_story_31210601_93_dialog_content = "São todas pessoas do seu domínio. Seu povo.",
  ui_story_31210601_94_dialog_content = "Maldito sanguessuga... Foi você que sugou a vida de nossas terras!",
  ui_story_31210601_95_dialog_content = "Esqueça nossa casa, você não dá a mínima para nossas vidas! Hoje vamos ensinar uma lição que você nunca esquecerá!",
  ui_story_31210601_96_dialog_content = "Seus caipiras sem um tostão... Você deveria estar agradecido pela oportunidade de trabalhar para mim!",
  ui_story_31210601_97_dialog_content = "Se você está tão desesperado por uma luta, deixe-me colocá-lo de volta em seu lugar!",
  ui_story_31210601_98_dialog_content = "Homens! Para mim!",
  ui_story_31210601_99_dialog_content = "\"Homens\"? Você quer dizer esses tolos arrependidos?",
  ui_story_31210601_100_dialog_content = "Desculpe desapontá-lo, mas eles estão presos há algum tempo.",
  ui_story_31210601_101_dialog_content = "(Droga... Dane-se! Não pode acabar assim! Deve haver um jeito...)",
  ui_story_31210601_102_dialog_content = "Espere, Meritíssimo! Certamente, você não tem nada a ver com uma louca como ela.",
  ui_story_31210601_103_dialog_content = "Ajude-me a deixar este lugar com segurança e farei tudo ao meu alcance para impulsioná-lo na hierarquia!",
  ui_story_31210601_104_dialog_content = "Mesmo a posição do juiz principal não está fora de questão!",
  ui_story_31210601_105_dialog_content = "Oh? Que mudança repentina de postura.",
  ui_story_31210601_106_dialog_content = "Não é seu dever proteger a segurança e a prosperidade dos nobres Lumo?",
  ui_story_31210601_107_dialog_content = "Esta pode ser sua chance de nos mostrar sua lealdade inabalável! Pense nisso!",
  ui_story_31210601_108_dialog_content = "Contanto que eles não ataquem você, não tenho motivos para interferir.",
  ui_story_31210601_109_dialog_content = "Além disso, sinto que devo corrigir uma de suas afirmações.",
  ui_story_31210601_110_dialog_content = "Minha lealdade inabalável é para com o Deus da Luz, e meu dever é defender a justiça e a ordem em Lumopolis, não os interesses da classe nobre.",
  ui_story_31210601_111_dialog_content = "O que você está falando?! Eles claramente me ameaçaram agora há pouco! Você não estava ouvindo?!",
  ui_story_31210601_112_dialog_content = "Ou essa \"justiça\" que vocês juízes adoram falar é nada mais do que formalidades vazias?!",
  ui_story_31210601_113_dialog_content = "Você estava seguro para fazer comentários rudes para seus próprios cidadãos antes, não é?",
  ui_story_31210601_114_dialog_content = "A lei se aplica a todos igualmente, e esta situação não é diferente.",
  ui_story_31210601_115_dialog_content = "Você não é menos hipócrita do que eu! Principalmente você, Paloma... Você é a pior de todas!",
  ui_story_31210601_116_dialog_content = "Você fala sobre odiar Lumopolis de todo o coração, mas está disposto a conspirar com um de seus juízes!",
  ui_story_31210601_117_dialog_content = "Estou disposto a reconhecer minha própria hipocrisia. Você é?",
  ui_story_31210601_118_dialog_content = "Hmph—!",
  ui_story_31210601_119_dialog_content = "Eu não sou nada como você. Agir de forma educada e gentil diante da nobreza, ao mesmo tempo em que trata os plebeus sem um pingo de decência.",
  ui_story_31210601_120_dialog_content = "E nunca afirmei que o que fiz hoje foi para o juiz de Lumopolis. Eu fiz tudo por mim.",
  ui_story_31210601_121_dialog_content = "Suas ações me deixaram mal do estômago naquele dia, então escolhi lidar com você. É simples assim.",
  ui_story_31210601_121X1_dialog_content = "Se PlayerName não tivesse me contado antes, eu teria acreditado que você realmente se juntou a uma gangue.",
  ui_story_31210601_122_dialog_content = "<color=#e8d9bb>Algumas horas antes...</color>",
  ui_story_31210601_123_dialog_content = "Pittman! Por aqui!",
  ui_story_31210601_124_dialog_content = "Nome do jogador? O que você está fazendo aqui?",
  ui_story_31210601_125_dialog_content = "E por que você está vestido como um membro de gangue?",
  ui_story_31210601_126_dialog_content = "Não há tempo para explicar! Apenas venha comigo! Pressa!",
  ui_story_31210601_127_dialog_content = "E-espere! Ainda tenho negócios urgentes para resolver!",
  ui_story_31210601_128_dialog_content = "Há alguns dias, um nobre de Lumópolis cruzou com Paloma, e mal consegui intervir antes que a situação piorasse.",
  ui_story_31210601_129_dialog_content = "Mas depois disso, não parecia que Paloma estava pronta para deixar o assunto de lado... Temo que ela esteja prestes a fazer algo terrível.",
  ui_story_31210601_130_dialog_content = "É por isso que não posso ir com você agora. Por favor me perdoe.",
  ui_story_31210601_131_dialog_content = "Paloma é quem me pediu para vir te encontrar, Pittman!",
  ui_story_31210601_132_dialog_content = "Ah, e não se esqueça! Você tem que fingir que foi nocauteado por mim mais tarde; faça com que pareça real para que não pareça uma encenação!",
  ui_story_31210601_133_dialog_content = "Você quer que eu aja...? Não entendo muito bem... Isso é algo que Paloma inventou?",
  ui_story_31210601_134_dialog_content = "Não se preocupe com isso! Você vai entender tudo quando vir o que acontece entre Paloma e aquele nobre, ok?",
  ui_story_31210601_135_dialog_content = "Ela não fará nada ilegal, eu prometo! Eu confio nela e você confia em mim... Certo?",
  ui_story_31210601_136_dialog_content = "Mesmo tendo me preparado mentalmente, ainda fiquei um tanto chocado no momento em que entrei.",
  ui_story_31210601_137_dialog_content = "Sério? E você, PlayerName?",
  ui_story_31210601_138_option_content = "É tudo graças ao seu disfarce.",
  ui_story_31210601_139_dialog_content = "Essa roupa realmente enfatiza sua presença legal e imponente.",
  ui_story_31210601_140_dialog_content = "Mesmo estando ao seu lado, poderia jurar que estava ao lado de um verdadeiro chefe de gangue!",
  ui_story_31210601_141_option_content = "Sua personalidade carregou o show.",
  ui_story_31210601_142_dialog_content = "Parecia que você nasceu para interpretar o líder das Rosas Negras.",
  ui_story_31210601_143_dialog_content = "Até eu tive dificuldade em lembrar que você não era um líder de gangue perverso!",
  ui_story_31210601_144_dialog_content = "Não ajuda que essa roupa pareça ter saído direto do seu guarda-roupa pessoal.",
  ui_story_31210601_145_dialog_content = "Hmph. Você está começando a soar como um amigo de verdade com toda essa bajulação.",
  ui_story_31210601_146_dialog_content = "Eu tenho que dizer, porém... essa roupa realmente combina com você também, PlayerName.",
  ui_story_31210601_147_dialog_content = "Tem certeza que não quer continuar como meu braço direito?",
  ui_story_31210601_148_dialog_content = "A-ahn?!",
  ui_story_31210601_149_dialog_content = "*Rindo* Só estou brincando.",
  ui_story_31210601_150_dialog_content = "Além disso, trabalho melhor sozinho. Eu nunca faria algo tão estúpido ou problemático quanto entrar para uma gangue.",
  ui_story_31210601_151_dialog_content = "O fato de você nunca ter pretendido atacar aquele nobre mostra que você amadureceu bastante, Paloma.",
  ui_story_31210601_152_dialog_content = "Quem, ele? Por favor, ele era um alvo fácil. Além disso, não estava com vontade de sujar meus espinhos.",
  ui_story_31210601_153_dialog_content = "Embora eu esteja tão surpreso que alguém tão teimoso e intrometido como você ficou quieto de lado enquanto tudo acontecia. Você também amadureceu um pouco, Pittman.",
  ui_story_31210601_154_dialog_content = "Eu simplesmente escolhi confiar em você e PlayerName desta vez... bem como minha própria capacidade de responder rapidamente, se a situação exigir.",
  ui_story_31210601_155_dialog_content = "Além disso, eu não queria prendê-lo pessoalmente, e é por isso que não permitiria que você fizesse nada ilegal na minha frente.",
  ui_story_31210601_156_dialog_content = "Bastante confiante em si mesmo, não é, Meritíssimo?",
  ui_story_31210601_157_dialog_content = "Aquelas pessoas lá fora vestidas de branco devem ser do Tribunal de Justiça.",
  ui_story_31210601_158_dialog_content = "Seus reforços chegaram mais rápido do que eu pensava.",
  ui_story_31210601_159_dialog_content = "Ela não estava brincando. A rua está cheia de Lumo Guards!",
  ui_story_31210601_160_dialog_content = "Quer dizer que você não ligou para eles?",
  ui_story_31210601_161_dialog_content = "Não, eu não fiz. Você fez?",
  ui_story_31210601_162_dialog_content = "Foi ela?",
  ui_story_31210601_163_dialog_content = "Paloma se foi...",
  ui_story_31210601_164_dialog_content = "Então... essa é a Rosa Negra, hein?",
  ui_story_31210601_165_dialog_content = "Como muito parecido com ela.",
  ui_story_31210602_1_dialog_content = "Ah... esses olhos luminescentes, o rosto presenteado pelos deuses... é como contemplar uma divindade!",
  ui_story_31210602_2_dialog_content = "Que esplêndido, a divindade que venero... minha deusa...!",
  ui_story_31210602_3_dialog_content = "Ah... Como é refrescante a brisa marinha!",
  ui_story_31210602_4_dialog_content = "EveToda vez que vou à praia, me sinto tão feliz. Então, o que eu faço agora?",
  ui_story_31210602_5_option_content = "Pegue conchas bonitas",
  ui_story_31210602_6_dialog_content = "Eu posso ser capaz de decorar o Colosso com algumas dessas conchas lindas.",
  ui_story_31210602_7_dialog_content = "Há muitos deles aqui. Parece que acertei na mosca.",
  ui_story_31210602_8_option_content = "Deite na areia",
  ui_story_31210602_9_dialog_content = "A areia aqui é tão delicada e macia, não consigo evitar querer deitar nela.",
  ui_story_31210602_10_dialog_content = "Hã? O que é esse espinho preto na areia? Alguém pode se machucar com isso... Acho que eu deveria realmente tirá-lo.",
  ui_story_31210602_11_dialog_content = "O que tá fazendo?",
  ui_story_31210602_12_dialog_content = "Uau?! O que você estava fazendo lá na areia?",
  ui_story_31210602_13_dialog_content = "Eu estava apenas deitado aqui aproveitando o sol até você começar a puxar meu maiô.",
  ui_story_31210602_14_dialog_content = "S-Desculpe, eu pensei que era algum tipo de espinho...",
  ui_story_31210602_15_dialog_content = "Se você realmente deseja se desculpar, gostaria que você me acompanhasse a algum lugar.",
  ui_story_31210602_16_dialog_content = "Hum... Aonde?",
  ui_story_31210602_17_dialog_content = "Você já ouviu falar da misteriosa seita aqui que adora a Deusa Espinheiro Ardente?",
  ui_story_31210602_18_dialog_content = "A Deusa Espinheiro Ardente? Nunca ouvi falar dela.",
  ui_story_31210602_19_dialog_content = "Pessoas comuns adoram criar esses falsos pequenos deuses.",
  ui_story_31210602_20_dialog_content = "A inteligência que adquiri indica que algo está estranho nesta seita, e eu planejo investigar isso.",
  ui_story_31210602_21_dialog_content = "Isso parece meio perigoso. Eu irei com você.",
  ui_story_31210602_22_dialog_content = "Mas antes de irmos, preciso trocar para minhas roupas normais.",
  ui_story_31210602_23_dialog_content = "Ei, o que vocês dois pensam que estão fazendo? Estranhos não são bem-vindos aqui! Fora com vocês!",
  ui_story_31210602_24_dialog_content = "<size=30>O que a gente faz agora? Eles não vão nos deixar entrar...</size>",
  ui_story_31210602_25_dialog_content = "<size=30>Não se preocupe, deixe isso comigo.</size>",
  ui_story_31210602_26_dialog_content = "Somos novos membros do rebanho e gostaríamos de participar da cerimônia de hoje.",
  ui_story_31210602_27_dialog_content = "Sangue novo, hein? Tem alguma prova? Você carrega o símbolo da Deusa Espinheiro do Fogo?",
  ui_story_31210602_28_dialog_content = "O sigilo da Deusa Espinheiro Ardente?",
  ui_story_31210602_29_dialog_content = "Isso—",
  ui_story_31210602_30_dialog_content = "(Ele acabou de tirar um pedaço curto de espinho afiado. Acho que a farsa acabou, não tem como passarmos por ele!)",
  ui_story_31210602_31_dialog_content = "É sobre isso que você está falando?",
  ui_story_31210602_32_dialog_content = "(Hã? Paloma realmente tem um desses?)",
  ui_story_31210602_33_dialog_content = "Isso mesmo. Este é o presente concedido a nós pela Deusa do Espinheiro Ardente—um presente que apenas os verdadeiros crentes podem possuir.",
  ui_story_31210602_34_dialog_content = "Você deveria ter me mostrado isso antes. Você pode entrar.",
  ui_story_31210602_35_dialog_content = "Como você conseguiu aquele símbolo?",
  ui_story_31210602_36_dialog_content = "Adivinhe.",
  ui_story_31210602_37_dialog_content = "Você conseguiu com seus poderes.",
  ui_story_31210602_38_dialog_content = "Acho que você não é tão sem graça afinal.",
  ui_story_31210602_39_dialog_content = "É uma coincidência que você possa manipular espinhos... Ainda bem que o símbolo não era uma barra de chocolate.",
  ui_story_31210602_40_dialog_content = "Você realmente acredita que foi uma coincidência?",
  ui_story_31210602_41_dialog_content = "O quê?",
  ui_story_31210602_42_dialog_content = "Parece que a cerimônia ainda não começou. Vamos encontrar um lugar para assistir às sombras.",
  ui_story_31210602_43_dialog_content = "Está tão escuro aqui. Eu pensei que todas as cerimônias religiosas acontecessem em espaços abertos e iluminados.",
  ui_story_31210602_44_dialog_content = "Nem todas as igrejas seguem a luz. Talvez só encontremos encantamentos misteriosos e oferendas aqui, ou até mesmo sacrifícios...",
  ui_story_31210602_45_dialog_content = "Não me assuste, eu não quero ser servido como um cordeiro no altar.",
  ui_story_31210602_46_dialog_content = "Não se preocupe. Essa ralé não tem coragem de sacrificar os vivos ainda.",
  ui_story_31210602_47_dialog_content = "Verdadeiros crentes, bem-vindos à cerimônia de hoje. Eu sou o mensageiro do Pastor.",
  ui_story_31210602_48_dialog_content = "Hoje, oferecemos nosso sacrifício mais precioso à Deusa Espinheiro Ardente - uma expressão de nosso amor e admiração por ela.",
  ui_story_31210602_49_dialog_content = "Louve a Deusa do Espinheiro Ardente! Louve o Pastor!",
  ui_story_31210602_50_dialog_content = "Vejo que temos algumas caras novas entre nós hoje. Claro, damos as boas-vindas à adição de sangue novo, mas primeiro vocês precisam nos apresentar suas ofertas.",
  ui_story_31210602_51_dialog_content = "Apenas após ser aprovado pelos nossos árbitros, você poderá se juntar oficialmente a nós.",
  ui_story_31210602_52_dialog_content = "Que tipo de ofertas? Eles não vão fazer nada conosco, não é?",
  ui_story_31210602_53_dialog_content = "Vamos ver o que os outros fazem primeiro.",
  ui_story_31210602_54_dialog_content = "Tenho uma oferta! Quero apresentá-la!",
  ui_story_31210602_55_dialog_content = "Um acólito apaixonado. Excelente! Por favor, junte-se a mim no palco.",
  ui_story_31210602_56_dialog_content = "Esta é uma foto que tirei de uma estrela-do-mar. Acho muito bonita e perfeita para expressar meu respeito pela Deusa Firethorn.",
  ui_story_31210602_57_dialog_content = "Uma estrela-do-mar? Você deseja oferecer uma estrela-do-mar à Deusa Firethorn? Você acha que uma simples estrela-do-mar tocaria o coração dela?",
  ui_story_31210602_58_dialog_content = "Ah, na verdade, eu acho que a estrela-do-mar que ele fotografou é realmente fofa.",
  ui_story_31210602_59_dialog_content = "Você esqueceu o foco dos nossos ensinamentos atuais? Você realmente acredita que o Pastor gostaria de ver algo tão medíocre e desinteressante? Próximo.",
  ui_story_31210602_60_dialog_content = "Olá a todos. A foto que quero compartilhar com vocês é de uma tartaruga marinha, que é um tipo de...",
  ui_story_31210602_61_dialog_content = "Zero pontos.",
  ui_story_31210602_62_dialog_content = "Zero pontos.",
  ui_story_31210602_63_dialog_content = "Cinco pontos. É uma ótima jogada. Tartarugas têm uma vida muito longa. Elas devem guardar muitas histórias e segredos.",
  ui_story_31210602_64_dialog_content = "Tartarugas são apenas répteis lentos e chatos. Você pode encontrar essas fotos em qualquer lugar. Elas não têm valor.",
  ui_story_31210602_65_dialog_content = "Éramos um clube de fotografia de biologia marinha e, mesmo que agora sejamos um—",
  ui_story_31210602_66_dialog_content = "Tranquilo! Próximo!",
  ui_story_31210602_67_dialog_content = "Alguns desses juízes são realmente severos, mas até agora, parece que essa igreja é basicamente apenas um grupo de fotógrafos da vida marinha.",
  ui_story_31210602_68_dialog_content = "Cada um deles possui um pequeno pedaço de piracanta. O que, por favor me diga, isso tem a ver com criaturas marinhas?",
  ui_story_31210602_69_dialog_content = "Bom... Acho que não há conexão ali.",
  ui_story_31210602_70_dialog_content = "Então, com certeza há algo mais profundo acontecendo com essa seita.",
  ui_story_31210602_71_dialog_content = "De qualquer forma, a diversão está prestes a começar.",
  ui_story_31210602_72_dialog_content = "Como assim?",
  ui_story_31210602_73_dialog_content = "As luzes se apagaram, os portões se fecharam e a vela azul foi acesa... Ah, essa falsa cerimônia de abençoada trapaça está prestes a começar.",
  ui_story_31210602_74_dialog_content = "O grande Pastor chegou, vamos todos recebê-lo com a mais calorosa salva de palmas!",
  ui_story_31210602_75_dialog_content = "Louve a Deusa do Espinheiro Ardente! Louve o Pastor!",
  ui_story_31210602_76_dialog_content = "Obrigado a todos por virem à nossa cerimônia mensal de oferendas. A poderosa Deusa Espinheiro do Fogo aguarda ansiosamente para receber as oferendas puras que vocês reuniram aqui para oferecer.",
  ui_story_31210602_77_dialog_content = "(Ofertas puras? Ele se refere a ouro e joias ou algo assim?)",
  ui_story_31210602_78_dialog_content = "Sua Santidade, por favor, permita-me dizer algumas palavras. Acabamos de avaliar as ofertas trazidas por alguns dos recém-chegados e constatamos que estão seriamente insuficientes!",
  ui_story_31210602_79_dialog_content = "Mas eu não quero ser muito duro com eles. Obviamente, eles não conseguiram entender as regras da cerimônia e precisam de algum tempo para se adaptar aos nossos costumes.",
  ui_story_31210602_80_dialog_content = "Agora, vamos começar nossa apresentação das verdadeiras ofertas. Contemple!",
  ui_story_31210602_81_dialog_content = "Ah, isso é incrível.",
  ui_story_31210602_82_dialog_content = "A iluminação e composição estão impecáveis, quase perfeitas!",
  ui_story_31210602_83_dialog_content = "Também preparei uma oferta para a Deusa Firethorn! Estas são fotos espontâneas que tirei de várias garotas na praia!",
  ui_story_31210602_84_dialog_content = "Uau! Olhe só suas ofertas! Elas realmente são algo especial! A Deusa do Espinheiro Ardente vai adorar isso!",
  ui_story_31210602_85_dialog_content = "Isso é nojento! Esses caras não são nada mais do que mirones! Que bando de tarados!",
  ui_story_31210602_86_dialog_content = "Pastor, por favor! Deixe-nos contemplar a Deusa do Espinheiro Ardente mais uma vez!",
  ui_story_31210602_87_dialog_content = "Muito bem. Chegou a hora de convidar a Deusa para o altar para que todos vocês possam adorá-la.",
  ui_story_31210602_88_dialog_content = "Saudações, Deusa—",
  ui_story_31210602_89_dialog_content = "Hã? A Deusa do Espinheiro Ardente é... uma foto?",
  ui_story_31210602_90_dialog_content = "O que são essas linhas pretas cruzadas na foto? Eu não entendo, mas de alguma forma parece familiar...",
  ui_story_31210602_91_dialog_content = "Então, foi ele!",
  ui_story_31210602_92_dialog_content = "Hã? Você encontrou algo?",
  ui_story_31210602_93_dialog_content = "Meus espinhos logo sufocarão a vida deste templo quebrado de desejo e pecado.",
  ui_story_31210602_94_dialog_content = "Sangue novo, você já entende que tipo de fotos deve tirar?",
  ui_story_31210602_95_dialog_content = "Bem, isso é tudo bastante bizarro, mas parece muito empolgante ao mesmo tempo. Estou disposto a participar!",
  ui_story_31210602_96_dialog_content = "Sinto-me um pouco envergonhado devido à minha idade avançada, mas também estou disposto a seguir o Pastor e a Deusa Espinheiro Ardente!",
  ui_story_31210602_97_dialog_content = "Por que esses dois novatos no canto não estão dizendo nada? Você ainda não apresentou nenhuma oferta, não é? Agora você pode ter o Pastor para guiá-lo pessoalmente.",
  ui_story_31210602_98_dialog_content = "Ah não, eles nos notaram.",
  ui_story_31210602_99_dialog_content = "Aqui, você pode aceitar esta foto como uma oferta.",
  ui_story_31210602_100_dialog_content = "Hum? Não é que—!",
  ui_story_31210602_101_dialog_content = "Apresse-se agora! Não desperdice o tempo do Pastor!",
  ui_story_31210602_102_dialog_content = "Ah, eu... Essa foto...",
  ui_story_31210602_103_dialog_content = "Deixe-me ver-",
  ui_story_31210602_104_dialog_content = "Não é essa a Deusa do Espinheiro Ardente?!",
  ui_story_31210602_105_dialog_content = "Quem é você? Como é possível que você tenha uma foto da Deusa Firethorn?!",
  ui_story_31210602_106_dialog_content = "Você sabe onde podemos encontrar a Deusa Espinheiro Ardente? Alguém! Qualquer um! Capture-o!",
  ui_story_31210602_107_dialog_content = "Eu não sei de nada...",
  ui_story_31210602_108_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_109_dialog_content = "Como ousa colocar as mãos nele!",
  ui_story_31210602_110_dialog_content = "Céus! É a Deusa Espinheiro Ardente! Ela desceu!",
  ui_story_31210602_111_dialog_content = "(Como a Paloma trocou de roupa tão rápido?)",
  ui_story_31210602_112_dialog_content = "É hora de acabar com essa farsa absurda.",
  ui_story_31210602_113_dialog_content = "Ugh! Que espinhos ferozes! Será essa a verdadeira natureza da Deusa Espinheiro de Fogo à qual eu rezo?",
  ui_story_31210602_114_dialog_content = "Deusa, sou seu seguidor mais leal! É a maior honra estar em sua presença!",
  ui_story_31210602_115_dialog_content = "Cala a arapuca!",
  ui_story_31210602_116_dialog_content = "Aaaaaahhhh!",
  ui_story_31210602_117_dialog_content = "É assim que a Deusa e o Pastor devem se relacionar? Tudo isso parece um pouco intenso demais para mim...",
  ui_story_31210602_118_dialog_content = "Não é isso. Ela é minha amiga, não a Deusa da sua seita distorcida. Todos vocês foram enganados pelo Pastor.",
  ui_story_31210602_119_dialog_content = "Dói, dói! Acho que estou prestes a morrer!",
  ui_story_31210602_120_dialog_content = "Você está disposto a revelar a verdade por trás dessa suposta seita agora? Conte-me tudo desde o começo.",
  ui_story_31210602_121_dialog_content = "*soluçando* Eu vou te contar! Eu vou te contar tudo!",
  ui_story_31210602_122_dialog_content = "Esta seita era originalmente uma sociedade de fotografia da vida marinha. Eu era apenas um dos membros, mas meu verdadeiro interesse é difícil de expressar...",
  ui_story_31210602_123_dialog_content = "Sob minha influência, este pequeno clube lentamente se transformou em uma assembleia excêntrica.",
  ui_story_31210602_124_dialog_content = "Há alguns meses, na praia, tirei uma foto de você usando um maiô divino, e desde então desejo vê-la novamente.",
  ui_story_31210602_125_dialog_content = "Quando apresentei sua foto em nosso encontro de fotografia, todos começaram a admirar sua beleza divina - como a de uma deusa.",
  ui_story_31210602_126_dialog_content = "Eu estava enfrentando problemas financeiros naquela época... Bem, não, eu queria cobrar dos membros, p-para sustentar o desenvolvimento da sociedade!",
  ui_story_31210602_127_dialog_content = "Então, eu usei suas fotos para criar uma série de lendas sobre a Deusa Firethorn, e nós gradualmente nos desenvolvemos no que temos hoje...",
  ui_story_31210602_128_dialog_content = "Uma história por trás da fundação da igreja. Preciso registrá-la no Livro de Doutrinas para os futuros crentes...",
  ui_story_31210602_129_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_130_dialog_content = "Ah, não! O Livro das Doutrinas foi rasgado em pedaços!",
  ui_story_31210602_131_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_132_dialog_content = "Ugh! Que surra brutal! Que dor!",
  ui_story_31210602_133_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_134_dialog_content = "Deusa, acalme sua fúria! Por favor, Deusa, pare de me chicotear! Ahhhh!",
  ui_story_31210602_135_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_136_dialog_content = "O desejo vergonhoso consumiu sua alma e razão. Suas chamadas doutrinas são apenas uma máscara de hipocrisia.",
  ui_story_31210602_137_dialog_content = "Se você continuar com essa perversão descarada, o verdadeiro julgamento irá te despedaçar sem piedade!",
  ui_story_31210602_138_dialog_content = "Ahh! Pare com os chicotes! Não vamos mais tirar fotos sorrateiras de garotas quentes, eu juro pelo Fireth—Não, eu juro pelo Deus da Luz!",
  ui_story_31210602_139_dialog_content = "Juro pelo Deus da Luz! Nunca mais farei algo assim novamente!",
  ui_story_31210602_140_dialog_content = "Ah, então todos vocês são de Lumópolis, isso explica muita coisa.",
  ui_story_31210602_141_dialog_content = "Ufa, finalmente entregamos aqueles canalhas para a Corte de Justiça.",
  ui_story_31210602_142_dialog_content = "Paloma mencionou querer ir à praia para relaxar. Eu deveria ir encontrá-la... Ela pode precisar de um pouco de ânimo depois de tudo isso.",
  ui_story_31210602_143_dialog_content = "(Paloma está... observando uma pequena estrela-do-mar?)",
  ui_story_31210602_144_dialog_content = "(Pela expressão de felicidade no rosto dela, parece que ela está curtindo ficar sozinha. É melhor eu não incomodá-la.)",
  ui_story_31210602_145_dialog_content = "Você veio até aqui só para sair?",
  ui_story_31210602_146_dialog_content = "Eu não queria incomodar você, então...",
  ui_story_31210602_147_dialog_content = "Tudo já foi resolvido?",
  ui_story_31210602_148_dialog_content = "Sim, a Corte de Justiça já começou a investigação.",
  ui_story_31210602_149_dialog_content = "Muito obrigado por tudo. Tenho sorte de ter você por perto para me ajudar a lidar com o incômodo insuportável de lidar com a Corte de Justiça.",
  ui_story_31210602_150_dialog_content = "Para que servem os amigos? Você está se sentindo melhor agora?",
  ui_story_31210602_151_dialog_content = "Parece que você me entendeu mal. Você realmente me vê como o tipo de pessoa que se abala facilmente com assuntos tão triviais?",
  ui_story_31210602_152_dialog_content = "Não, é só que a maioria das pessoas não se sentiria muito bem com o que aconteceu.",
  ui_story_31210602_153_dialog_content = "Claro, especialmente as meninas que foram violadas.",
  ui_story_31210602_154_dialog_content = "Eles originalmente pretendiam desfrutar de uma estadia paradisíaca aqui, mas foram maliciosamente violados por malfeitores insidiosos.",
  ui_story_31210602_155_dialog_content = "Sim... Ainda bem que você pegou os bandidos antes daquelas fotos viralizarem.",
  ui_story_31210602_156_dialog_content = "Even se as fotos se espalhassem pelo continente, não são essas garotas que deveriam sentir vergonha e arrependimento, e sofrer consequências tão ultrajantes.",
  ui_story_31210602_157_dialog_content = "Estou curioso... O que você acha daquelas pessoas?",
  ui_story_31210602_158_option_content = "Eles são apenas um conjunto de criaturas patéticas, dominadas por desejos básicos.",
  ui_story_31210602_159_option_content = "Esses caras são tão nojentos! Eca!",
  ui_story_31210602_160_dialog_content = "Eles forjaram uma máscara de hipocrisia em nome de uma falsa divindade para encobrir sua própria feiura e desprezo.",
  ui_story_31210602_161_dialog_content = "A religião deveria ser pura e edificante, com ideais elevados e esperanças inspiradoras para o futuro, mas muitas vezes é usada pelos mal-intencionados para envenenar o mundo.",
  ui_story_31210602_162_dialog_content = "Hmn! Muito certo!",
  ui_story_31210602_163_dialog_content = "Para ser honesto, eu não entendo muito bem todas essas grandes ideias. Na verdade, ainda estou um pouco preocupado com você e aquelas fotos que aquele cara tirou de você...",
  ui_story_31210602_164_dialog_content = "Por que você estaria preocupado comigo? Eu não fiz nada de errado.",
  ui_story_31210602_165_dialog_content = "Eu nunca deixaria algo assim me abalar. Não há nada de errado com o que eu visto, e me sinto magnífico.",
  ui_story_31210602_166_dialog_content = "Quanto àqueles malfeitores sem vergonha, eu os derrotarei com honra e integridade, todas as vezes!",
  ui_story_31210602_167_dialog_content = "E foi exatamente isso que você fez!",
  ui_story_31210602_168_dialog_content = "A propósito, essa foto que você me deu mais cedo... Você quer ela de volta?",
  ui_story_31210602_169_dialog_content = "É uma selfie minha usando um maiô. Você acha isso desagradável?",
  ui_story_31210602_170_dialog_content = "Claro que não. Você está tão linda e confiante nesta foto.",
  ui_story_31210602_171_dialog_content = "Pense nisso como um presente de um amigo!",
  ui_story_31210602_172_dialog_content = "(Esta foto de Paloma encarando a câmera com tanta ousadia é simplesmente de tirar o fôlego... É um milhão de vezes mais bonita do que as tiradas sem ela saber das sombras...)",
  ui_story_31210602_173_dialog_content = "(Se ao menos houvesse alguma maneira de impedir as pessoas de fazerem coisas assim... Maytalvez eu possa discutir essa questão com Paloma no futuro...)"
}
return config
